table.sql:
CREATE TABLE IF NOT EXISTS profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  username TEXT UNIQUE NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- RLS Policies
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own profile"
  ON profiles FOR SELECT
  USING (auth.uid() = id);

CREATE POLICY "Users can update own profile"
  ON profiles FOR UPDATE
  USING (auth.uid() = id);

CREATE TABLE IF NOT EXISTS accounts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  base_ccy TEXT DEFAULT 'USD',
  starting_cash NUMERIC(15,2) DEFAULT 10000.00,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(user_id, name)
);

CREATE INDEX IF NOT EXISTS idx_accounts_user ON accounts(user_id);

-- RLS Policies
ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own accounts"
  ON accounts FOR SELECT
  USING (user_id IN (SELECT id FROM profiles WHERE id = auth.uid()));

CREATE POLICY "Users can insert own accounts"
  ON accounts FOR INSERT
  WITH CHECK (user_id IN (SELECT id FROM profiles WHERE id = auth.uid()));

CREATE POLICY "Users can update own accounts"
  ON accounts FOR UPDATE
  USING (user_id IN (SELECT id FROM profiles WHERE id = auth.uid()));

CREATE TABLE IF NOT EXISTS orders (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  ticker TEXT NOT NULL,
  side TEXT NOT NULL CHECK (side IN ('BUY', 'SELL')),
  qty INTEGER NOT NULL CHECK (qty > 0),
  order_type TEXT NOT NULL CHECK (order_type IN ('MARKET', 'LIMIT', 'STOP')),
  limit_price NUMERIC(15,4) NULL,
  stop_price NUMERIC(15,4) NULL,
  status TEXT NOT NULL CHECK (status IN ('PENDING', 'ACCEPTED', 'FILLED', 'PARTIAL', 'CANCELLED', 'REJECTED')),
  submitted_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_orders_account ON orders(account_id);
CREATE INDEX IF NOT EXISTS idx_orders_ticker ON orders(ticker);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);

-- RLS Policies
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own orders"
  ON orders FOR SELECT
  USING (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE POLICY "Users can insert own orders"
  ON orders FOR INSERT
  WITH CHECK (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE POLICY "Users can update own orders"
  ON orders FOR UPDATE
  USING (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE TABLE IF NOT EXISTS fills (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  ticker TEXT NOT NULL,
  side TEXT NOT NULL CHECK (side IN ('BUY', 'SELL')),
  qty INTEGER NOT NULL CHECK (qty > 0),
  price NUMERIC(15,4) NOT NULL,
  fee NUMERIC(15,4) DEFAULT 0.0,
  filled_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_fills_order ON fills(order_id);
CREATE INDEX IF NOT EXISTS idx_fills_account ON fills(account_id);
CREATE INDEX IF NOT EXISTS idx_fills_ticker ON fills(ticker);

-- RLS Policies
ALTER TABLE fills ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own fills"
  ON fills FOR SELECT
  USING (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE POLICY "Users can insert own fills"
  ON fills FOR INSERT
  WITH CHECK (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE TABLE IF NOT EXISTS positions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  ticker TEXT NOT NULL,
  qty INTEGER NOT NULL,
  avg_cost NUMERIC(15,4) NOT NULL,
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(account_id, ticker)
);

CREATE INDEX IF NOT EXISTS idx_positions_account ON positions(account_id);
CREATE INDEX IF NOT EXISTS idx_positions_ticker ON positions(ticker);

-- RLS Policies
ALTER TABLE positions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own positions"
  ON positions FOR SELECT
  USING (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE POLICY "Users can insert own positions"
  ON positions FOR INSERT
  WITH CHECK (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE POLICY "Users can update own positions"
  ON positions FOR UPDATE
  USING (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE POLICY "Users can delete own positions"
  ON positions FOR DELETE
  USING (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE TABLE IF NOT EXISTS ledger (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  amount NUMERIC(15,2) NOT NULL,
  balance_after NUMERIC(15,2) NOT NULL,
  entry_type TEXT NOT NULL CHECK (entry_type IN ('INITIAL', 'TRADE', 'FEE', 'DIVIDEND', 'DEPOSIT', 'WITHDRAWAL')),
  reference_id UUID NULL,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_ledger_account ON ledger(account_id);
CREATE INDEX IF NOT EXISTS idx_ledger_type ON ledger(entry_type);

-- RLS Policies
ALTER TABLE ledger ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own ledger"
  ON ledger FOR SELECT
  USING (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE POLICY "Users can insert own ledger"
  ON ledger FOR INSERT
  WITH CHECK (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE TABLE IF NOT EXISTS portfolio_snapshots (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  equity NUMERIC(15,2) NOT NULL,
  cash NUMERIC(15,2) NOT NULL,
  market_value NUMERIC(15,2) NOT NULL,
  unrealized_pnl NUMERIC(15,2) NOT NULL,
  realized_pnl NUMERIC(15,2) NOT NULL,
  snapshot_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_snapshots_account ON portfolio_snapshots(account_id);
CREATE INDEX IF NOT EXISTS idx_snapshots_time ON portfolio_snapshots(snapshot_at);

-- RLS Policies
ALTER TABLE portfolio_snapshots ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own snapshots"
  ON portfolio_snapshots FOR SELECT
  USING (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE POLICY "Users can insert own snapshots"
  ON portfolio_snapshots FOR INSERT
  WITH CHECK (account_id IN (SELECT id FROM accounts WHERE user_id IN (SELECT id FROM profiles WHERE id = auth.uid())));

CREATE TABLE IF NOT EXISTS ml_regimes ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticker TEXT NOT NULL, window TEXT NOT NULL, window_start TIMESTAMPTZ NOT NULL, window_end TIMESTAMPTZ NOT NULL, cluster_id INTEGER NOT NULL CHECK (cluster_id IN (0, 1, 2)), pct_ask NUMERIC(5,2), pct_bid NUMERIC(5,2), avg_spread NUMERIC(10,4), avg_trade_size NUMERIC(12,2), volatility NUMERIC(10,6), volume_zscore NUMERIC(8,4), computed_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(ticker, window, window_start) );
CREATE INDEX IF NOT EXISTS idx_regimes_ticker ON ml_regimes(ticker); CREATE INDEX IF NOT EXISTS idx_regimes_window ON ml_regimes(window);
-- RLS Policies (public read for ML data) ALTER TABLE ml_regimes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view regimes" ON ml_regimes FOR SELECT TO authenticated USING (true);
CREATE POLICY "Authenticated users can insert regimes" ON ml_regimes FOR INSERT TO authenticated WITH CHECK (true);

CREATE TABLE IF NOT EXISTS ml_forecasts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticker TEXT NOT NULL, timeframe TEXT NOT NULL, as_of_date TIMESTAMPTZ NOT NULL, prob_cluster_0 NUMERIC(5,4) NOT NULL, prob_cluster_1 NUMERIC(5,4) NOT NULL, prob_cluster_2 NUMERIC(5,4) NOT NULL, model_type TEXT NOT NULL, computed_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(ticker, timeframe, as_of_date) );
CREATE INDEX IF NOT EXISTS idx_forecasts_ticker ON ml_forecasts(ticker); CREATE INDEX IF NOT EXISTS idx_forecasts_date ON ml_forecasts(as_of_date);
-- RLS Policies (public read for ML data) ALTER TABLE ml_forecasts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view forecasts" ON ml_forecasts FOR SELECT TO authenticated USING (true);
CREATE POLICY "Authenticated users can insert forecasts" ON ml_forecasts FOR INSERT TO authenticated WITH CHECK (true);

function.implementation_notes:
- Require at least 30 windows of history for training
- If insufficient data, return uniform probabilities {0.33, 0.33, 0.33}
- Model type: "LogisticRegression" or "RandomForest"

