# === PHASE 2: Mark Price Function ===
def _mark_price(self, ticker: str) -> float:
    """
    Return current mark price for ticker based on config.MARK_PRICE_SOURCE.

    'LAST_TRADE': return last trade price from WebSocket
    'MIDPOINT': return (bid + ask) / 2

    Falls back to last trade price if midpoint unavailable.
    """
    if config.MARK_PRICE_SOURCE == "MIDPOINT":
        if hasattr(self, 'current_bid') and hasattr(self, 'current_ask'):
            if self.current_bid and self.current_ask and self.current_bid > 0 and self.current_ask > 0:
                return (self.current_bid + self.current_ask) / 2.0

    # Fallback to last trade price
    if hasattr(self, 'current_price') and self.current_price:
        return self.current_price

    # Last resort: return 0 (will cause broker to reject order)
    return 0.0

# === PHASE 2: Broker Signal Handlers ===
@pyqtSlot(str)
def onOrderAccepted(self, order_id: str):
    """Handle order accepted event."""
    # Trade tab will handle blotter update
    pass

@pyqtSlot(object)
def onOrderFilled(self, fill):
    """Handle order filled event."""
    # Trade tab will handle blotter and position updates
    pass

@pyqtSlot(list)
def onPositionsUpdated(self, positions):
    """Update Trade tab positions display."""
    if hasattr(self, 'tradeTab'):
        self.tradeTab.updatePositions(positions)

@pyqtSlot(dict)
def onPortfolioUpdated(self, portfolio):
    """Update Trade tab portfolio header."""
    if hasattr(self, 'tradeTab'):
        self.tradeTab.updatePortfolio(portfolio)

@pyqtSlot(str)
def onOmsError(self, error_msg: str):
    """Display OMS error in status bar or message box."""
    QMessageBox.warning(self, "Order Error", error_msg)

@pyqtSlot(str)
def onLoadTickerFromTrade(self, ticker: str):
    """Load ticker when requested from Trade tab position click."""
    self.tickerInput.setText(ticker)
    self.loadTicker()

# === PHASE 2: Refresh Portfolio on Price Update ===
try:
    if self.broker:
        self.broker.refresh_portfolio()
except Exception as e:
    logging.debug(f"Portfolio refresh error: {e}")

# === PHASE 2: Append Trade to Time & Sales Tape ===
try:
    if hasattr(self, 'infoTab') and hasattr(self.infoTab, 'tapeWidget'):
        self.infoTab.tapeWidget.appendTrade(trade)
except Exception as e:
    logging.debug(f"Tape append error: {e}")

# === PHASE 2: Load Time & Sales Tape ===
try:
    if hasattr(self, 'infoTab') and hasattr(self.infoTab, 'tapeWidget'):
        if config.TAPE_BACKFILL_ENABLED:
            self.infoTab.tapeWidget.loadTicker(ticker)
except Exception as e:
    logging.warning(f"Tape load error: {e}")

# === PHASE 2: Sign Out on Close ===
try:
    sign_out()
except Exception as e:
    logging.debug(f"Sign out error: {e}")

