from dataclasses import dataclass, field from typing import Optional from datetime import datetime
@dataclass class Account: """Trading account (paper trading portfolio).""" id: str user_id: str name: str base_ccy: str = "USD" starting_cash: float = 10000.0 cash: float = 10000.0 equity: float = 10000.0 created_at: Optional[datetime] = None updated_at: Optional[datetime] = None
@dataclass class Order: """Order record.""" id: str account_id: str ticker: str side: str # "BUY" or "SELL" qty: int order_type: str # "MARKET", "LIMIT", "STOP" status: str # "PENDING", "ACCEPTED", "FILLED", "PARTIAL", "CANCELLED", "REJECTED" limit_price: Optional[float] = None stop_price: Optional[float] = None submitted_at: Optional[datetime] = None updated_at: Optional[datetime] = None
@dataclass class Fill: """Trade execution (fill).""" id: str order_id: str account_id: str ticker: str side: str # "BUY" or "SELL" qty: int price: float fee: float = 0.0 filled_at: Optional[datetime] = None
@dataclass class Position: """Current position in a ticker.""" id: Optional[str] account_id: str ticker: str qty: int avg_cost: float updated_at: Optional[datetime] = None
@dataclass class PortfolioSnapshot: """Point-in-time portfolio snapshot.""" id: Optional[str] account_id: str equity: float cash: float market_value: float unrealized_pnl: float realized_pnl: float snapshot_at: Optional[datetime] = None
